package com.termux.app.workspace;
import android.app.*;import android.widget.*;import android.os.Looper;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class OpenCodeStatusUiTest {
 private Activity activity(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();a.setTheme(com.termux.R.style.Theme_Termux_Black);return a;}
 private JSONObject settings(String access,String mode)throws Exception{return new JSONObject().put("session","ses_fixture").put("revision",new String(new char[64]).replace('\0','a')).put("scope","project").put("access",access).put("mode",mode).put("canChange",true);}
 private void idleUntil(AlertDialog dialog)throws Exception{for(int i=0;i<200;i++){Shadows.shadowOf(Looper.getMainLooper()).idle();if(dialog.getButton(AlertDialog.BUTTON_POSITIVE).isEnabled())return;Thread.sleep(5);}fail("UI operation did not settle");}
 @Test public void nativeAcknowledgmentUpdatesOnlyRequestedSettingAndRetainsScope()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.aiAgent="opencode";p.aiAccess="ask";p.aiMode="build";p.aiProjectOnly=true;AtomicInteger saved=new AtomicInteger(),mutated=new AtomicInteger();OpenCodeStatusUi.Rpc rpc=q->{if(q.optString("op").equals("status"))return new JSONObject().put("nativeChat",true).put("id","ses_fixture");if(q.optString("op").equals("settings-read"))return settings("ask","build");mutated.incrementAndGet();assertEquals("settings-permissions",q.getString("op"));assertEquals("ses_fixture",q.getString("session"));return new JSONObject().put("applied",true).put("settings",settings(q.getString("access"),"build"));};OpenCodeStatusUi ui=new OpenCodeStatusUi(activity(),p,saved::incrementAndGet,rpc);ui.show();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();try{idleUntil(dialog);TextView rights=dialog.getWindow().getDecorView().findViewWithTag("agent-status-permissions");assertTrue(rights.isEnabled());rights.performClick();AlertDialog choice=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals(3,choice.getListView().getCount());choice.getListView().performItemClick(choice.getListView().getChildAt(0),0,0);assertEquals(0,mutated.get());AlertDialog confirm=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();confirm.getButton(AlertDialog.BUTTON_POSITIVE).performClick();idleUntil(dialog);assertEquals(1,mutated.get());assertEquals(1,saved.get());assertEquals("full",p.aiAccess);assertEquals("build",p.aiMode);assertTrue(p.aiProjectOnly);}finally{dialog.dismiss();}}
 @Test public void ambiguousAcknowledgmentDoesNotPersistAndDisablesRetryUntilRefresh()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.aiAgent="opencode";p.aiAccess="ask";AtomicInteger saved=new AtomicInteger();OpenCodeStatusUi ui=new OpenCodeStatusUi(activity(),p,saved::incrementAndGet,q->{if(q.optString("op").equals("status"))return new JSONObject().put("nativeChat",true).put("id","ses_fixture");if(q.optString("op").equals("settings-read"))return settings("ask","build");throw new java.io.IOException("ambiguous timeout");});ui.show();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();try{idleUntil(dialog);Method apply=OpenCodeStatusUi.class.getDeclaredMethod("apply",JSONObject.class,boolean.class,String.class);apply.setAccessible(true);apply.invoke(ui,settings("ask","build"),true,"full");idleUntil(dialog);assertEquals("ask",p.aiAccess);assertEquals(0,saved.get());assertFalse(dialog.getWindow().getDecorView().findViewWithTag("agent-status-permissions").isEnabled());}finally{dialog.dismiss();}}
 @Test public void rejectsForeignSettingsSnapshot()throws Exception{assertTrue(OpenCodeStatusUi.validSettings(settings("ask","build"),"ses_fixture"));assertFalse(OpenCodeStatusUi.validSettings(settings("ask","build"),"ses_other"));assertFalse(OpenCodeStatusUi.validSettings(settings("ask","build").put("revision","bad"),"ses_fixture"));}
}
